-- supabase/sql/exam_question_bank_neet_pg_set6.sql
--
-- Sixth curated question-bank batch for 'NEET PG' (see exam_patterns_neet_pg.sql for the exam's
-- structure, and Sets 1-5 for the earlier batches -- same table/schema, no migration needed).
-- All-new questions, no overlap with Sets 1 through 5.
--
-- Same format as the earlier sets: every row is format='mcq' with a single isCorrect:true option,
-- matching NEET PG's 100% single-best-response format. 16 chapters (8 Pre-/Para-Clinical
-- Sciences, 4 Clinical Medicine and Allied, 2 Surgery and Allied, 2 Obstetrics/Gynaecology/
-- Anesthesia) each get 4 questions, covering classic, high-yield MBBS/board-style facts.
--
-- Run this once in the Supabase SQL Editor, after exam_patterns_neet_pg.sql and
-- exam_question_bank_neet_pg_set1.sql through set5.sql.

insert into exam_question_bank (exam_name, subject, chapter, difficulty, format, text, options, numerical_answer, explanation) values

-- Anatomy
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'medium', 'mcq',
 'The Circle of Willis, an anastomotic ring of arteries, is formed at the base of which organ?',
 '[{"text":"The heart","isCorrect":false},{"text":"The brain","isCorrect":true},{"text":"The liver","isCorrect":false},{"text":"The kidney","isCorrect":false}]'::jsonb,
 null, 'The Circle of Willis is an anastomotic arterial ring located at the base of the brain, providing collateral blood supply between the anterior and posterior cerebral circulations.'),
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'medium', 'mcq',
 'In males, the inguinal canal primarily transmits the:',
 '[{"text":"Spermatic cord","isCorrect":true},{"text":"Sciatic nerve","isCorrect":false},{"text":"Femoral artery","isCorrect":false},{"text":"Ureter","isCorrect":false}]'::jsonb,
 null, 'The inguinal canal in males transmits the spermatic cord, which contains the vas deferens, testicular vessels, and associated nerves.'),
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'medium', 'mcq',
 'Injury to the common peroneal nerve classically causes which deformity?',
 '[{"text":"Foot drop","isCorrect":true},{"text":"Claw hand","isCorrect":false},{"text":"Wrist drop","isCorrect":false},{"text":"Winging of the scapula","isCorrect":false}]'::jsonb,
 null, 'Common peroneal nerve injury paralyzes the dorsiflexors and evertors of the foot, causing the characteristic foot drop.'),
('NEET PG', 'Pre- and Para-Clinical Sciences', 'Anatomy', 'medium', 'mcq',
 'Taste sensation from the anterior two-thirds of the tongue is carried by which cranial nerve?',
 '[{"text":"Glossopharyngeal nerve (CN IX)","isCorrect":false},{"text":"Facial nerve (CN VII), via the chorda tympani","isCorrect":true},{"text":"Vagus nerve (CN X)","isCorrect":false},{"text":"Hypoglossal nerve (CN XII)","isCorrect":false}]'::jsonb,
 null, 'Taste sensation from the anterior two-thirds of the tongue is carried by the facial nerve via its chorda tympani branch, while the posterior third is served by the glossopharyngeal nerve.'),

